data AccountTemplate = AccountTemplate
  { accountTemplateAdUnderscoreaccountUnderscoreid :: Maybe Text -- ^ ID of the Ad Account that owns the template
  , accountTemplateAdUnderscoreaccountUnderscoreids :: Maybe [Text] -- ^ IDs of the Ad Accounts that have access to this template
  , accountTemplateAdeUnderscorecolumns :: Maybe [Text] -- ^ A list of ADE columns
  , accountTemplateAttributionUnderscoretype :: Maybe Value -- ^ Attribution type for Brand/Category/SKU reports
  , accountTemplateClickUnderscorewindowUnderscoredays :: Maybe Double -- ^ The length of the sliding window over which click conversions will be attributed
  , accountTemplateColumns :: Maybe [ReportingColumn] -- ^ A list of columns to be included in the report
  , accountTemplateConversionUnderscorereportUnderscoretimeUnderscoretype :: Maybe ConversionReportTimeType -- ^ Conversion report time type
  , accountTemplateCreationUnderscoresource :: Maybe CreationSource -- ^ The surface used to create this template
  , accountTemplateCustomUnderscorecolumnUnderscoreids :: Maybe [Text] -- ^ A list of custom column IDs
  , accountTemplateDisplayUnderscoremetadata :: Maybe Text -- ^ Additional metadata about this reporting template
  , accountTemplateEngagementUnderscorewindowUnderscoredays :: Maybe Double -- ^ The length of the sliding window over which engagement conversions will be attributed
  , accountTemplateFiltersUnderscorejson :: Maybe Text -- ^ A JSON representation of any filters to be applied before returning report data. Each filter object should contain all of the following fields:\\ \"field\": The column name\\ \"operator\": The operator. Allowed operators: [\"=\", \"!=\", \"in\", \"not_in\", \"~\", \">\", \"<\", \"contains_substring\"]\\ \"value\": A single value or a list of values
  , accountTemplateGranularity :: Maybe Granularity -- ^ 
  , accountTemplateId :: Text -- ^ Template ID
  , accountTemplateIngestionUnderscoresources :: Maybe [IngestionSource] -- ^ The filter on the conversion ingestion source method for conversion metrics
  , accountTemplateIsUnderscoredefault :: Maybe Bool -- ^ A boolean representing if this is the default view that loads for this template type
  , accountTemplateIsUnderscoredeleted :: Maybe Bool -- ^ A boolean that indicates if the template has been deleted
  , accountTemplateIsUnderscoreownedUnderscorebyUnderscoreuser :: Maybe Bool -- ^ A boolean value that indicates if the user owns the template
  , accountTemplateIsUnderscorescheduled :: Maybe Bool -- ^ A boolean value that indicates if this template has been used to create a scheduled report
  , accountTemplateName :: Maybe Text -- ^ Template Name
  , accountTemplateReportUnderscoreendUnderscorerelativeUnderscoredaysUnderscoreinUnderscorepast :: Maybe Double -- ^ The number of days prior to the day the report will be delivered at which the report will end
