  , accountTemplateReportUnderscorestartUnderscorerelativeUnderscoredaysUnderscoreinUnderscorepast :: Maybe Double -- ^ The number of days prior to the day the report will be delivered at which the report will start
  , accountTemplateReportingUnderscoretimeUnderscorezone :: Maybe ReportingTimeZone -- ^ Timezone for reporting data
  , accountTemplateSortUnderscoreby :: Maybe Value -- ^ Unified metric sort configuration
  , accountTemplateType :: Maybe Text -- ^ Type of the template
  , accountTemplateUpdatedUnderscoretime :: Maybe Double -- ^ Time of last update in seconds since Unix epoch
  , accountTemplateUserUnderscoreid :: Maybe Text -- ^ ID of the user who created the template
