-- | Object describing the catalogs items batch
data CatalogsItemsBatch = CatalogsItemsBatch
  { catalogsItemsBatchBatchUnderscoreid :: Maybe Text -- ^ Id of the catalogs items batch
  , catalogsItemsBatchCatalogUnderscoretype :: Text -- ^ 
  , catalogsItemsBatchCompletedUnderscoretime :: Maybe UTCTime -- ^ Date and time (UTC) of the batch completion: YYYY-MM-DD'T'hh:mm:ss
  , catalogsItemsBatchCreatedUnderscoretime :: UTCTime -- ^ Date and time (UTC) of the batch creation: YYYY-MM-DD'T'hh:mm:ss
  , catalogsItemsBatchItems :: Maybe [CreativeAssetsProcessingRecord] -- ^ Array with the catalogs items processing records part of the catalogs items batch
  , catalogsItemsBatchStatus :: Maybe BatchOperationStatus -- ^ 
  } deriving (Show, Eq, Generic, Data)

instance FromJSON CatalogsItemsBatch where
  parseJSON = genericParseJSON optionsCatalogsItemsBatch
instance ToJSON CatalogsItemsBatch where
  toJSON = genericToJSON optionsCatalogsItemsBatch

optionsCatalogsItemsBatch :: Options
optionsCatalogsItemsBatch =
  defaultOptions
    { omitNothingFields  = True
    , fieldLabelModifier = \s -> fromMaybe ("did not find JSON field name for " ++ show s) $ lookup s table
    }
  where
    table =
      [ ("catalogsItemsBatchBatchUnderscoreid", "batch_id")
      , ("catalogsItemsBatchCatalogUnderscoretype", "catalog_type")
      , ("catalogsItemsBatchCompletedUnderscoretime", "completed_time")
      , ("catalogsItemsBatchCreatedUnderscoretime", "created_time")
      , ("catalogsItemsBatchItems", "items")
      , ("catalogsItemsBatchStatus", "status")
      ]


-- | 
data CatalogsItemsBatchPostRequest = CatalogsItemsBatchPostRequest
  { catalogsItemsBatchPostRequestCatalogUnderscoreid :: Maybe Text -- ^ Catalog id pertaining to the creative assets item. If not provided, default to oldest creative assets catalog
  , catalogsItemsBatchPostRequestCatalogUnderscoretype :: Text -- ^ 
